import{_ as e,o as n,c as s,a0 as i}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"Panduan module","description":"","frontmatter":{},"headers":[],"relativePath":"id_ID/guide/module.md","filePath":"id_ID/guide/module.md"}'),t={name:"id_ID/guide/module.md"};function l(d,a,o,r,p,u){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="panduan-module" tabindex="-1">Panduan module <a class="header-anchor" href="#panduan-module" aria-label="Permalink to &quot;Panduan module&quot;">​</a></h1><p>KernelSU menyediakan mekanisme modul yang mencapai efek memodifikasi direktori sistem dengan tetap menjaga integritas partisi sistem. Mekanisme ini umumnya dikenal sebagai &quot;tanpa sistem&quot;.</p><p>Mekanisme modul KernelSU hampir sama dengan Magisk. Jika Anda terbiasa dengan pengembangan modul Magisk, mengembangkan modul KernelSU sangat mirip. Anda dapat melewati pengenalan modul di bawah ini dan hanya perlu membaca <a href="./difference-with-magisk.html">difference-with-magisk</a>.</p><div class="warning custom-block"><p class="custom-block-title">METAMODULE HANYA DIPERLUKAN UNTUK MODIFIKASI FILE SISTEM</p><p>KernelSU menggunakan arsitektur <a href="./metamodule.html">metamodule</a> untuk me-mount direktori <code>system</code>. <strong>Hanya jika modul Anda perlu memodifikasi file <code>/system</code></strong> (melalui direktori <code>system</code>) Anda perlu menginstal metamodule (seperti <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>). Fitur modul lainnya seperti skrip, aturan sepolicy, dan system.prop bekerja tanpa metamodule.</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>Modul KernelSU mendukung tampilan antarmuka dan interaksi dengan pengguna. Lihat <a href="./module-webui.html">WebUI documentation</a> untuk detailnya.</p><h2 id="konfigurasi-modul" tabindex="-1">Konfigurasi Modul <a class="header-anchor" href="#konfigurasi-modul" aria-label="Permalink to &quot;Konfigurasi Modul&quot;">​</a></h2><p>KernelSU menyediakan sistem konfigurasi bawaan yang memungkinkan modul menyimpan pengaturan key-value persisten atau sementara. Untuk detail lebih lanjut, lihat <a href="./module-config.html">dokumentasi Konfigurasi Modul</a>.</p><h2 id="skrip-sekali-jalan" tabindex="-1">Skrip Sekali Jalan <a class="header-anchor" href="#skrip-sekali-jalan" aria-label="Permalink to &quot;Skrip Sekali Jalan&quot;">​</a></h2><p>ZIP modul juga dapat berupa skrip sekali jalan yang dijalankan satu kali oleh manajer KernelSU alih-alih dipasang. Untuk detail lebih lanjut, lihat <a href="./module-script.html">dokumentasi Skrip Sekali Jalan</a>.</p><h2 id="busybox" tabindex="-1">Busybox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;Busybox&quot;">​</a></h2><p>KernelSU dikirimkan dengan fitur biner BusyBox yang lengkap (termasuk dukungan penuh SELinux). Eksekusi terletak di <code>/data/adb/ksu/bin/busybox</code>. BusyBox KernelSU mendukung &quot;Mode Shell Standalone Shell&quot; yang dapat dialihkan waktu proses. Apa yang dimaksud dengan mode mandiri ini adalah bahwa ketika dijalankan di shell <code>ash</code> dari BusyBox, setiap perintah akan langsung menggunakan applet di dalam BusyBox, terlepas dari apa yang ditetapkan sebagai <code>PATH</code>. Misalnya, perintah seperti <code>ls</code>, <code>rm</code>, <code>chmod</code> <strong>TIDAK</strong> akan menggunakan apa yang ada di <code>PATH</code> (dalam kasus Android secara default akan menjadi <code>/system/bin/ls</code>, <code> /system/bin/rm</code>, dan <code>/system/bin/chmod</code> masing-masing), tetapi akan langsung memanggil applet BusyBox internal. Ini memastikan bahwa skrip selalu berjalan di lingkungan yang dapat diprediksi dan selalu memiliki rangkaian perintah lengkap, apa pun versi Android yang menjalankannya. Untuk memaksa perintah <em>not</em> menggunakan BusyBox, Anda harus memanggil yang dapat dieksekusi dengan path lengkap.</p><p>Setiap skrip shell tunggal yang berjalan dalam konteks KernelSU akan dieksekusi di shell <code>ash</code> BusyBox dengan mode mandiri diaktifkan. Untuk apa yang relevan dengan pengembang pihak ke-3, ini termasuk semua skrip boot dan skrip instalasi modul.</p><p>Bagi yang ingin menggunakan fitur “Standalone Mode” ini di luar KernelSU, ada 2 cara untuk mengaktifkannya:</p><ol><li>Tetapkan variabel lingkungan <code>ASH_STANDALONE</code> ke <code>1</code><br>Contoh: <code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>Beralih dengan opsi baris perintah:<br><code>/data/adb/ksu/bin/busybox sh -o mandiri &lt;script&gt;</code></li></ol><p>Untuk memastikan semua shell <code>sh</code> selanjutnya dijalankan juga dalam mode mandiri, opsi 1 adalah metode yang lebih disukai (dan inilah yang digunakan secara internal oleh KernelSU dan manajer KernelSU) karena variabel lingkungan diwariskan ke proses anak.</p><p>::: perbedaan tip dengan Magisk</p><p>BusyBox KernelSU sekarang menggunakan file biner yang dikompilasi langsung dari proyek Magisk. <strong>Berkat Magisk!</strong> Oleh karena itu, Anda tidak perlu khawatir tentang masalah kompatibilitas antara skrip BusyBox di Magisk dan KernelSU karena keduanya persis sama! :::</p><h2 id="kernelsu-module" tabindex="-1">KernelSU module <a class="header-anchor" href="#kernelsu-module" aria-label="Permalink to &quot;KernelSU module&quot;">​</a></h2><p>Modul KernelSU adalah folder yang ditempatkan di <code>/data/adb/modules</code> dengan struktur di bawah ini:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- The folder is named with the ID of the module</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Module Identity ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- This file stores the metadata of the module</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Main Contents ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- This folder will be mounted if skip_mount does not exist</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Status Flags ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- If exists, KernelSU will NOT mount your system folder</span></span>
<span class="line"><span>│   ├── disable             &lt;--- If exists, the module will be disabled</span></span>
<span class="line"><span>│   ├── remove              &lt;--- If exists, the module will be removed next reboot</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Optional Files ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- This script will be executed in post-fs-data</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- This script will be executed in late_start service</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- This script will be executed when KernelSU removes your module</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- Properties in this file will be loaded as system properties by resetprop</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- Additional custom sepolicy rules</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- File .rc di direktori ini akan disuntikkan ke init.rc saat boot</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Auto Generated, DO NOT MANUALLY CREATE OR MODIFY ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- A symlink to $MODID/system/vendor</span></span>
<span class="line"><span>│   ├── product             &lt;--- A symlink to $MODID/system/product</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- A symlink to $MODID/system/system_ext</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Any additional files / folders are allowed ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><p>::: perbedaan tip dengan Magisk KernelSU tidak memiliki dukungan bawaan untuk Zygisk, jadi tidak ada konten terkait Zygisk dalam modul. Namun, Anda dapat menggunakan <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> untuk mendukung modul Zygisk. Dalam hal ini, konten modul Zygisk identik dengan yang didukung oleh Magisk. :::</p><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p>module.prop adalah file konfigurasi untuk sebuah modul. Di KernelSU, jika modul tidak berisi file ini, maka tidak akan dikenali sebagai modul. Format file ini adalah sebagai berikut:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versioncode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (opsional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (opsional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (opsional)</span></span></code></pre></div><ul><li><code>id</code> harus cocok dengan ekspresi reguler ini: <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code><br> contoh: ✓ <code>a_module</code>, ✓ <code>a.module</code>, ✓ <code>module-101</code>, ✗ <code>a module</code>, ✗ <code>1_module</code>, ✗ <code>-a-module</code><br> Ini adalah <strong>pengidentifikasi unik</strong> modul Anda. Anda tidak boleh mengubahnya setelah dipublikasikan.</li><li><code>versionCode</code> harus berupa <strong>integer</strong>. Ini digunakan untuk membandingkan versi.</li><li>Lainnya yang tidak disebutkan di atas dapat berupa string <strong>satu baris</strong>.</li><li>Pastikan untuk menggunakan tipe jeda baris <code>UNIX (LF)</code> dan bukan <code>Windows (CR+LF)</code> atau <code>Macintosh (CR)</code>.</li><li><code>actionIcon</code> dan <code>webuiIcon</code> adalah path ikon opsional yang digunakan sebagai ikon default untuk pintasan aksi modul dan pintasan WebUI modul di aplikasi pengelola. Path ini harus relatif terhadap direktori root modul. Contohnya, <code>actionIcon=icon/icon.png</code> akan dipetakan ke <code>&lt;MODDIR&gt;/icon/icon.png</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">DESKRIPSI DINAMIS</p><p>Field <code>description</code> dapat diganti secara dinamis saat runtime menggunakan sistem konfigurasi modul. Lihat <a href="./module-config.html#overriding-module-description">Mengganti Deskripsi Modul</a> untuk detailnya.</p></div><h3 id="shell-skrip" tabindex="-1">Shell skrip <a class="header-anchor" href="#shell-skrip" aria-label="Permalink to &quot;Shell skrip&quot;">​</a></h3><p>Harap baca bagian <a href="#boot-scripts">Boot Scripts</a> untuk memahami perbedaan antara <code>post-fs-data.sh</code> dan <code>service.sh</code>. Untuk sebagian besar pengembang modul, <code>service.sh</code> sudah cukup baik jika Anda hanya perlu menjalankan skrip boot.</p><p>Di semua skrip modul Anda, harap gunakan <code>MODDIR=\${0%/*}</code> untuk mendapatkan jalur direktori dasar modul Anda; lakukan <strong>TIDAK</strong> hardcode jalur modul Anda dalam skrip.</p><p>::: perbedaan tip dengan Magisk Anda dapat menggunakan variabel lingkungan KSU untuk menentukan apakah skrip berjalan di KernelSU atau Magisk. Jika berjalan di KernelSU, nilai ini akan disetel ke true. :::</p><h3 id="system-directory" tabindex="-1"><code>system</code> directory <a class="header-anchor" href="#system-directory" aria-label="Permalink to &quot;\`system\` directory&quot;">​</a></h3><p>Isi direktori ini akan dihamparkan di atas partisi sistem /sistem setelah sistem di-boot. Ini berarti bahwa:</p><div class="tip custom-block"><p class="custom-block-title">PERSYARATAN METAMODULE</p><p>Direktori <code>system</code> hanya di-mount jika Anda telah menginstal metamodule yang menyediakan fungsionalitas mounting (seperti <code>meta-overlayfs</code>). Metamodule menangani bagaimana modul di-mount. Lihat <a href="./metamodule.html">Panduan Metamodule</a> untuk informasi lebih lanjut.</p></div><ol><li>File dengan nama yang sama dengan yang ada di direktori terkait di sistem akan ditimpa oleh file di direktori ini.</li><li>Folder dengan nama yang sama dengan yang ada di direktori terkait di sistem akan digabungkan dengan folder di direktori ini.</li></ol><p>Jika Anda ingin menghapus file atau folder di direktori sistem asli, Anda perlu membuat file dengan nama yang sama dengan file/folder di direktori modul menggunakan <code>mknod filename c 0 0</code>. Dengan cara ini, sistem overlayfs akan secara otomatis &quot;memutihkan&quot; file ini seolah-olah telah dihapus (partisi / sistem sebenarnya tidak diubah).</p><p>Anda juga dapat mendeklarasikan variabel bernama <code>REMOVE</code> yang berisi daftar direktori di <code>customize.sh</code> untuk menjalankan operasi penghapusan, dan KernelSU akan secara otomatis mengeksekusi <code>mknod &lt;TARGET&gt; c 0 0</code> di direktori modul yang sesuai. Misalnya:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HAPUS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/sistem/aplikasi/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Daftar di atas akan mengeksekusi <code>mknod $MODPATH/system/app/YouTuBe c 0 0</code> dan <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>; dan <code>/system/app/YouTube</code> dan <code>/system/app/Bloatware</code> akan dihapus setelah modul berlaku.</p><p>Jika Anda ingin mengganti direktori di sistem, Anda perlu membuat direktori dengan jalur yang sama di direktori modul Anda, lalu atur atribut <code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code> untuk direktori ini. Dengan cara ini, sistem overlayfs akan secara otomatis mengganti direktori terkait di sistem (tanpa mengubah partisi /sistem).</p><p>Anda dapat mendeklarasikan variabel bernama <code>REPLACE</code> di file <code>customize.sh</code> Anda, yang menyertakan daftar direktori yang akan diganti, dan KernelSU akan secara otomatis melakukan operasi yang sesuai di direktori modul Anda. Misalnya:</p><p>REPLACE=&quot; /system/app/YouTube /system/app/Bloatware &quot;</p><p>Daftar ini akan secara otomatis membuat direktori <code>$MODPATH/system/app/YouTube</code> dan <code>$MODPATH/system/app/Bloatware</code>, lalu jalankan <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/ YouTube</code> dan <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/Bloatware</code>. Setelah modul berlaku, <code>/system/app/YouTube</code> dan <code>/system/app/Bloatware</code> akan diganti dengan direktori kosong.</p><p>::: perbedaan tip dengan Magisk</p><p>KernelSU menggunakan arsitektur <a href="./metamodule.html">metamodule</a> di mana mounting didelegasikan ke metamodule yang dapat dipasang. Metamodule <code>meta-overlayfs</code> resmi menggunakan OverlayFS kernel untuk modifikasi systemless, sedangkan Magisk menggunakan magic mount (bind mount) yang dibangun langsung ke dalam intinya. Keduanya mencapai tujuan yang sama: memodifikasi file <code>/system</code> tanpa memodifikasi partisi <code>/system</code> secara fisik. Pendekatan KernelSU memberikan lebih banyak fleksibilitas dan mengurangi permukaan deteksi. :::</p><p>Jika Anda tertarik dengan overlayfs, disarankan untuk membaca <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">dokumentasi overlayfs</a> Kernel Linux.</p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>File ini mengikuti format yang sama dengan <code>build.prop</code>. Setiap baris terdiri dari <code>[kunci]=[nilai]</code>.</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>Jika modul Anda memerlukan beberapa tambalan sepolicy tambahan, harap tambahkan aturan tersebut ke dalam file ini. Setiap baris dalam file ini akan diperlakukan sebagai pernyataan kebijakan.</p><h3 id="initrc-injection" tabindex="-1">Injeksi initrc <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;Injeksi initrc {#initrc-injection}&quot;">​</a></h3><p>KernelSU menyediakan mekanisme untuk menyuntikkan arahan Android Init RC kustom ke dalam <code>init.rc</code> sistem. Hal ini memungkinkan modul untuk mendaftarkan layanan Android kustom, mengatur pemicu properti, atau melakukan tindakan bahasa Init lainnya tanpa memodifikasi partisi sistem.</p><p>Selama boot, modul kernel KernelSU mencegat panggilan sistem <code>read()</code> dan <code>fstat()</code>. Saat proses init Android membaca <code>/system/etc/init/hw/init.rc</code>, KernelSU secara transparan menambahkan konten RC kustom ke bagian akhir file. Proses init menguraikan arahan yang disuntikkan ini sama seperti konten init.rc asli.</p><p>Di sisi userspace, ksud menggabungkan semua file <code>.rc</code> dari modul yang diaktifkan menjadi satu file <code>modules.rc</code>, yang disimpan di partisi <code>/metadata</code>. File ini secara otomatis dibuat ulang setiap kali status modul berubah (diinstal, diaktifkan, dinonaktifkan, dihapus, dll.).</p><h4 id="file-initrc-modul" tabindex="-1">File initrc modul <a class="header-anchor" href="#file-initrc-modul" aria-label="Permalink to &quot;File initrc modul&quot;">​</a></h4><p>Buat subdirektori <code>initrc/</code> di direktori modul Anda dan letakkan file <code>.rc</code> Anda di sana:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>File harus memiliki ekstensi <code>.rc</code>.</li><li>Selama modul diaktifkan, semua file <code>.rc</code> di direktori <code>initrc/</code> akan disertakan (izin eksekusi tidak diperlukan).</li><li>File diproses dalam <strong>urutan abjad nama file</strong> di dalam direktori, dan modul diproses dalam <strong>urutan abjad ID modul</strong>.</li></ul></div><h4 id="file-initrc-umum" tabindex="-1">File initrc umum <a class="header-anchor" href="#file-initrc-umum" aria-label="Permalink to &quot;File initrc umum&quot;">​</a></h4><p>Selain file RC tingkat modul, Anda dapat menempatkan file <code>.rc</code> di direktori global:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">File initrc umum memerlukan izin eksekusi</p><p>Tidak seperti direktori <code>initrc/</code> modul, file di <code>/data/adb/initrc.d/</code> <strong>harus memiliki izin eksekusi</strong> untuk disertakan. File <code>.rc</code> yang tidak dapat dieksekusi akan dilewati secara diam-diam.</p></div><p>File <code>initrc.d/</code> umum diproses sebelum file RC modul apa pun.</p><h4 id="contoh" tabindex="-1">Contoh <a class="header-anchor" href="#contoh" aria-label="Permalink to &quot;Contoh&quot;">​</a></h4><p>Berikut adalah contoh file <code>.rc</code> yang mendaftarkan layanan Android kustom:</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>Jika file ini ditempatkan di <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>, itu akan mendaftarkan layanan bernama <code>myservice</code> saat boot dan memulainya ketika <code>sys.boot_completed=1</code> tercapai.</p><h4 id="penyegaran-manual" tabindex="-1">Penyegaran Manual <a class="header-anchor" href="#penyegaran-manual" aria-label="Permalink to &quot;Penyegaran Manual&quot;">​</a></h4><p>Anda dapat memicu pembuatan ulang <code>modules.rc</code> secara manual dengan perintah berikut (perubahan berlaku pada boot berikutnya):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Injeksi initrc terjadi sangat awal dalam proses boot (saat init membaca init.rc), <strong>sebelum</strong> post-fs-data dan skrip modul apa pun dieksekusi.</li><li>Konten RC yang disuntikkan diperlakukan oleh init sebagai bagian dari init.rc asli, mendukung semua sintaks bahasa Android Init (definisi layanan, pemicu, pengaturan properti, dll.).</li><li>Injeksi initrc <strong>tidak tersedia</strong> dalam <strong>mode late-load</strong>, karena hook panggilan sistem tidak diinstal dalam mode tersebut.</li><li>Injeksi RC modul dapat dinonaktifkan dengan meneruskan parameter <code>--no-custom-rc</code> saat menambal gambar dengan ksud.</li></ul></div><h2 id="pemasangan-module" tabindex="-1">Pemasangan module <a class="header-anchor" href="#pemasangan-module" aria-label="Permalink to &quot;Pemasangan module&quot;">​</a></h2><p>Penginstal modul KernelSU adalah modul KernelSU yang dikemas dalam file zip yang dapat di-flash di aplikasi pengelola KernelSU. Pemasang modul KernelSU yang paling sederhana hanyalah modul KernelSU yang dikemas sebagai file zip.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Optional, more details later)</span></span>
<span class="line"><span>│                                           This script will be sourced by update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* The rest of module&#39;s files */</span></span>
<span class="line"><span>│</span></span></code></pre></div><p>:::peringatan Modul KernelSU TIDAK didukung untuk diinstal dalam pemulihan kustom!! :::</p><h3 id="kostumisasi" tabindex="-1">Kostumisasi <a class="header-anchor" href="#kostumisasi" aria-label="Permalink to &quot;Kostumisasi&quot;">​</a></h3><p>Jika Anda perlu menyesuaikan proses penginstalan modul, secara opsional Anda dapat membuat skrip di penginstal bernama <code>customize.sh</code>. Skrip ini akan <em>sourced</em> (tidak dijalankan!) oleh skrip penginstal modul setelah semua file diekstrak dan izin default serta konteks sekon diterapkan. Ini sangat berguna jika modul Anda memerlukan penyiapan tambahan berdasarkan ABI perangkat, atau Anda perlu menyetel izin khusus/konteks kedua untuk beberapa file modul Anda.</p><p>Jika Anda ingin sepenuhnya mengontrol dan menyesuaikan proses penginstalan, nyatakan <code>SKIPUNZIP=1</code> di <code>customize.sh</code> untuk melewati semua langkah penginstalan default. Dengan melakukannya, <code>customize.sh</code> Anda akan bertanggung jawab untuk menginstal semuanya dengan sendirinya.</p><p>Skrip <code>customize.sh</code> berjalan di shell BusyBox <code>ash</code> KernelSU dengan &quot;Mode Mandiri&quot; diaktifkan. Variabel dan fungsi berikut tersedia:</p><h4 id="variable" tabindex="-1">Variable <a class="header-anchor" href="#variable" aria-label="Permalink to &quot;Variable&quot;">​</a></h4><ul><li><code>KSU</code> (bool): variabel untuk menandai bahwa skrip berjalan di lingkungan KernelSU, dan nilai variabel ini akan selalu benar. Anda dapat menggunakannya untuk membedakan antara KernelSU dan Magisk.</li><li><code>KSU_VER</code> (string): string versi dari KernelSU yang diinstal saat ini (mis. <code>v0.4.0</code>)</li><li><code>KSU_VER_CODE</code> (int): kode versi KernelSU yang terpasang saat ini di ruang pengguna (mis. <code>10672</code>)</li><li><code>KSU_KERNEL_VER_CODE</code> (int): kode versi KernelSU yang terpasang saat ini di ruang kernel (mis. <code>10672</code>)</li><li><code>BOOTMODE</code> (bool): selalu <code>true</code> di KernelSU</li><li><code>MODPATH</code> (jalur): jalur tempat file modul Anda harus diinstal</li><li><code>TMPDIR</code> (jalur): tempat di mana Anda dapat menyimpan file untuk sementara</li><li><code>ZIPFILE</code> (jalur): zip instalasi modul Anda</li><li><code>ARCH</code> (string): arsitektur CPU perangkat. Nilainya adalah <code>arm</code>, <code>arm64</code>, <code>x86</code>, atau <code>x64</code></li><li><code>IS64BIT</code> (bool): <code>true</code> jika <code>$ARCH</code> adalah <code>arm64</code> atau <code>x64</code></li><li><code>API</code> (int): level API (versi Android) perangkat (mis. <code>23</code> untuk Android 6.0)</li><li><code>KSU_UAPI_VER</code> (int): versi UAPI ruang pengguna KernelSU (ksud) (mis. <code>2</code>). Versi ini bertambah ketika ada perubahan yang merusak kompatibilitas pada driver kernel, dan dapat digunakan oleh modul untuk memeriksa kompatibilitas.</li><li><code>KSU_RUNTIME_MODE</code> (string): mode runtime KernelSU saat ini. Nilai yang mungkin adalah <code>built-in</code> (mode GKI, dikompilasi ke dalam kernel), <code>lkm</code> (dimuat sebagai modul kernel saat boot), atau <code>late-load</code> (dimuat sebagai modul kernel setelah boot).</li><li><code>KSU_LATE_LOAD</code> (int?): jika KernelSU dimuat secara terlambat setelah boot, variabel ini diatur ke <code>1</code>; jika tidak, variabel ini tidak diatur.</li></ul><p>::: peringatan Di KernelSU, MAGISK_VER_CODE selalu 25200 dan MAGISK_VER selalu v25.2. Tolong jangan gunakan kedua variabel ini untuk menentukan apakah itu berjalan di KernelSU atau tidak. :::</p><h4 id="fungsi" tabindex="-1">Fungsi <a class="header-anchor" href="#fungsi" aria-label="Permalink to &quot;Fungsi&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    print &lt;msg&gt; to console</span></span>
<span class="line"><span>    Avoid using &#39;echo&#39; as it will not display in custom recovery&#39;s console</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    print error message &lt;msg&gt; to console and terminate the installation</span></span>
<span class="line"><span>    Avoid using &#39;exit&#39; as it will skip the termination cleanup steps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    this function is a shorthand for the following commands:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    for all files in &lt;directory&gt;, it will call:</span></span>
<span class="line"><span>       set_perm file owner group filepermission context</span></span>
<span class="line"><span>    for all directories in &lt;directory&gt; (including itself), it will call:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h2 id="boot-scripts" tabindex="-1">Boot scripts <a class="header-anchor" href="#boot-scripts" aria-label="Permalink to &quot;Boot scripts&quot;">​</a></h2><p>Di KernelSU, skrip dibagi menjadi dua jenis berdasarkan mode operasinya: mode post-fs-data dan mode layanan late_start:</p><ul><li>mode pasca-fs-data <ul><li>Tahap ini adalah BLOKIR. Proses boot dijeda sebelum eksekusi selesai, atau 10 detik telah berlalu.</li><li>Skrip dijalankan sebelum modul apa pun dipasang. Ini memungkinkan pengembang modul untuk menyesuaikan modul mereka secara dinamis sebelum dipasang.</li><li>Tahap ini terjadi sebelum Zygote dimulai, yang berarti segalanya di Android</li><li><strong>PERINGATAN:</strong> menggunakan <code>setprop</code> akan menghentikan proses booting! Silakan gunakan <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code> sebagai gantinya.</li><li><strong>Hanya jalankan skrip dalam mode ini jika perlu.</strong></li></ul></li><li>mode layanan late_start <ul><li>Tahap ini NON-BLOCKING. Skrip Anda berjalan paralel dengan proses booting lainnya.</li><li><strong>Ini adalah tahap yang disarankan untuk menjalankan sebagian besar skrip.</strong></li></ul></li></ul><p>Di KernelSU, skrip startup dibagi menjadi dua jenis berdasarkan lokasi penyimpanannya: skrip umum dan skrip modul:</p><ul><li>Skrip Umum <ul><li>Ditempatkan di <code>/data/adb/post-fs-data.d</code> atau <code>/data/adb/service.d</code></li><li>Hanya dieksekusi jika skrip disetel sebagai dapat dieksekusi (<code>chmod +x script.sh</code>)</li><li>Skrip di <code>post-fs-data.d</code> berjalan dalam mode post-fs-data, dan skrip di <code>service.d</code> berjalan di mode layanan late_start.</li><li>Modul seharusnya <strong>TIDAK</strong> menambahkan skrip umum selama instalasi</li></ul></li><li>Skrip Modul <ul><li>Ditempatkan di folder modul itu sendiri</li><li>Hanya dijalankan jika modul diaktifkan</li><li><code>post-fs-data.sh</code> berjalan dalam mode post-fs-data, dan <code>service.sh</code> berjalan dalam mode layanan late_start.</li></ul></li></ul><p>Semua skrip boot akan berjalan di shell BusyBox <code>ash</code> KernelSU dengan &quot;Mode Mandiri&quot; diaktifkan.</p><h2 id="late-load-mode" tabindex="-1">Mode late-load <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Mode late-load {#late-load-mode}&quot;">​</a></h2><p>Selain alur boot standar yang dijelaskan di atas, KernelSU mendukung <strong>mode late-load</strong> untuk skenario LKM (Loadable Kernel Module). Dalam mode ini, modul kernel KernelSU dimuat <strong>setelah sistem sepenuhnya boot</strong>, bukan selama proses init.</p><h3 id="kapan-late-load-terjadi" tabindex="-1">Kapan late-load terjadi? <a class="header-anchor" href="#kapan-late-load-terjadi" aria-label="Permalink to &quot;Kapan late-load terjadi?&quot;">​</a></h3><p>Late-load dipicu dengan menjalankan perintah <code>ksud late-load</code>. Perintah ini:</p><ol><li>Mendeteksi versi KMI saat ini dan memuat <code>kernelsu.ko</code> yang sesuai dari aset tertanam.</li><li>Melakukan inisialisasi modul (aturan SELinux, daftar izin, fitur, dll.) yang biasanya terjadi saat boot.</li></ol><p>Karena sistem sudah sepenuhnya berjalan, mekanisme tertentu saat boot tidak tersedia atau tidak diperlukan.</p><h3 id="perbedaan-dari-boot-standar" tabindex="-1">Perbedaan dari boot standar <a class="header-anchor" href="#perbedaan-dari-boot-standar" aria-label="Permalink to &quot;Perbedaan dari boot standar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Perilaku</th><th style="text-align:center;">Boot standar</th><th style="text-align:center;">Mode late-load</th></tr></thead><tbody><tr><td>Modul kernel dimuat oleh init (PID 1)</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Tidak (dimuat setelah boot)</td></tr><tr><td>Hook kprobe ksud (execve/read/fstat/input)</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Dilewati</td></tr><tr><td>Deteksi mode aman (tombol volume)</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Selalu dinonaktifkan</td></tr><tr><td>Pengambilan log boot (logcat/dmesg)</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Dilewati</td></tr><tr><td>Pemeriksaan koeksistensi Magisk</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Dilewati</td></tr><tr><td>Event <code>post-fs-data</code> dilaporkan ke kernel</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Dilewati</td></tr><tr><td>Event <code>boot-completed</code> dilaporkan ke kernel</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Diatur langsung saat init</td></tr><tr><td>Skrip <code>post-fs-data.sh</code> / <code>post-fs-data.d/</code></td><td style="text-align:center;">Ya</td><td style="text-align:center;">Digantikan oleh tahap <code>late-load</code></td></tr><tr><td>Pemuatan <code>system.prop</code></td><td style="text-align:center;">Ya</td><td style="text-align:center;">Ya</td></tr><tr><td>Mount OverlayFS (metamodule)</td><td style="text-align:center;">Ya</td><td style="text-align:center;">Ya</td></tr><tr><td>Skrip <code>post-mount.sh</code> / <code>post-mount.d/</code></td><td style="text-align:center;">Ya</td><td style="text-align:center;">Ya</td></tr><tr><td>Skrip <code>service.sh</code> / <code>service.d/</code></td><td style="text-align:center;">Ya</td><td style="text-align:center;">Ya</td></tr><tr><td>Skrip <code>boot-completed.sh</code> / <code>boot-completed.d/</code></td><td style="text-align:center;">Ya</td><td style="text-align:center;">Ya</td></tr><tr><td>Variabel lingkungan <code>KSU_LATE_LOAD</code></td><td style="text-align:center;">Tidak diatur</td><td style="text-align:center;">Diatur ke <code>1</code></td></tr><tr><td>Flag info kernel <code>0x4</code></td><td style="text-align:center;">Tidak diatur</td><td style="text-align:center;">Diatur</td></tr></tbody></table><h3 id="urutan-eksekusi-skrip" tabindex="-1">Urutan eksekusi skrip <a class="header-anchor" href="#urutan-eksekusi-skrip" aria-label="Permalink to &quot;Urutan eksekusi skrip&quot;">​</a></h3><p>Dalam mode late-load, urutan eksekusi skrip adalah:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. Muat kernelsu.ko (jika belum dimuat)</span></span>
<span class="line"><span>  2. Ekstrak biner, tangani pembaruan modul, muat aturan SELinux, inisialisasi fitur</span></span>
<span class="line"><span>  3. Jalankan skrip late-load.d/ dan skrip late-load modul (blocking)</span></span>
<span class="line"><span>  4. Muat system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. Jalankan skrip mount metamodule (OverlayFS)</span></span>
<span class="line"><span>  6. Jalankan skrip post-mount.d/ dan post-mount.sh modul (blocking)</span></span>
<span class="line"><span>  7. Jalankan skrip service.d/ dan service.sh modul (non-blocking)</span></span>
<span class="line"><span>  8. Jalankan skrip boot-completed.d/ dan boot-completed.sh modul (non-blocking)</span></span></code></pre></div><h3 id="skrip-khusus-late-load" tabindex="-1">Skrip khusus late-load <a class="header-anchor" href="#skrip-khusus-late-load" aria-label="Permalink to &quot;Skrip khusus late-load&quot;">​</a></h3><p>Modul dapat menyediakan skrip <code>late-load.sh</code> yang dijalankan <strong>hanya</strong> dalam mode late-load, sebagai pengganti <code>post-fs-data.sh</code>. Skrip ini berjalan sebelum mount OverlayFS, mirip dengan <code>post-fs-data.sh</code> dalam alur standar.</p><p>Selain itu, skrip umum dapat ditempatkan di <code>/data/adb/late-load.d/</code> untuk dijalankan pada tahap ini.</p><h3 id="mendeteksi-mode-late-load-dalam-skrip" tabindex="-1">Mendeteksi mode late-load dalam skrip <a class="header-anchor" href="#mendeteksi-mode-late-load-dalam-skrip" aria-label="Permalink to &quot;Mendeteksi mode late-load dalam skrip&quot;">​</a></h3><p>Modul dapat mendeteksi mode late-load dengan memeriksa variabel lingkungan <code>KSU_LATE_LOAD</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Berjalan dalam mode late-load</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>Ini memungkinkan modul menyesuaikan perilakunya, misalnya melewatkan operasi yang hanya diperlukan saat boot awal.</p>`,108)])])}const m=e(t,[["render",l]]);export{k as __pageData,m as default};
